package com.zhibrary.book;
import org.springframework.stereotype.Service; import java.util.*;
@Service public class BookService { private final BookRepository repo; public BookService(BookRepository repo){this.repo=repo;} public List<Book> search(String q){return q==null||q.isBlank()?repo.findAll():repo.findByTitleContainingIgnoreCaseOrIsbnContainingIgnoreCaseOrCategoryContainingIgnoreCaseOrAuthorContainingIgnoreCase(q,q,q,q);} public Book add(Book b){if(repo.findByIsbn(b.getIsbn()).isPresent())throw new IllegalArgumentException("ISBN already exists");return repo.save(b);} public Book update(Long id,Book input){Book b=repo.findById(id).orElseThrow(); if(repo.findByIsbn(input.getIsbn()).filter(x->!x.getId().equals(id)).isPresent())throw new IllegalArgumentException("ISBN already exists"); b.update(input.getTitle(),input.getIsbn(),input.getAuthor(),input.getCategory(),input.getPublicationYear(),input.getCoverImage()); return repo.save(b);} public Book setStatus(Long id,BookStatus status){Book b=repo.findById(id).orElseThrow();b.setStatus(status);return repo.save(b);} public void delete(Long id){repo.deleteById(id);} }
